<section class="page-intro shell"><span class="eyebrow">WISHLIST</span><h1>আপনার পছন্দের তালিকা।</h1><p>পছন্দের পণ্য এখানে রেখে পরে আবার দেখতে পারবেন।</p></section><section class="section shell"><?php if(empty($data['wishlist'])): ?><div class="empty-state"><h2>এখনো তালিকায় কিছু নেই।</h2><a class="button button-green" href="/shop">পণ্য খুঁজুন</a></div><?php else: ?><div class="product-grid"><?php foreach($data['wishlist'] as $product): ?><article class="product-card"><a class="product-image" href="/product/<?= e($product['slug']) ?>"><img src="<?= e($product['image_url']?:asset('category-home.jpg')) ?>" alt="<?= e($product['name']) ?>" loading="lazy"></a><div class="product-info"><h3><a href="/product/<?= e($product['slug']) ?>"><?= e($product['name']) ?></a></h3><div class="product-bottom"><span class="price"><?= e(format_price((float)$product['price'],$product['currency'])) ?></span><form action="/account/wishlist" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><button class="button button-outline" type="submit">সরান</button></form></div><?php if((int)$product['stock_quantity']>0): ?><form action="/cart/add" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><input type="hidden" name="quantity" value="1"><button class="button button-green button-full" type="submit">কার্টে যোগ করুন</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
